def Sum_of_Inverse_Divisors(n, m):
    def gcd(a, b):
        while a != 0:
            a, b = b % a, a
        return b
    def inv(x, m):
        return pow(x, m-2, m)
    S = sum(gcd(i, m) for i in range(1, m+1)) * inv(gcd(m, n), n)
    return S
