def lbs(arr):
    # Initialize arrays to store lengths of最长 increasing subsequence (lis) and decreasing subsequence (dls)
    lis = [1] * len(arr)
    dls = [1] * len(arr)

    # Build the lis array from left to right
    for i in range(1, len(arr)):
        for j in range(0, i):
            if arr[j] < arr[i] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Build the dls array from right to left
    for i in range(len(arr) - 2, -1, -1):
        for j in range(len(arr) - 1, i, -1):
            if arr[j] < arr[i] and dls[i] < dls[j] + 1:
                dls[i] = dls[j] + 1

    # Calculate the length of the longest bitonic subsequence
    max_length = 0
    for i in range(len(arr)):
        max_length = max(max_length, lis[i] + dls[i] - 1)  # Subtract 1 as the element is counted twice

    return max_length
