def dealnnoy_num(n, k):
    # Base case: nth Delannoy number equals 1 for k less than or equal to n
    if k <= n:
        return 1

    # Initialize the matrix to store delannoy numbers
    matrix = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Fill the 2D matrix with delannoy numbers
    for i in range(n + 1):
        for j in range(k + 1):
            if i == 0 and j == 0:
                matrix[i][j] = 1
            elif i == 0:
                matrix[i][j] = j
            elif j == 0:
                matrix[i][j] = i
            else:
                matrix[i][j] = matrix[i - 1][j] + matrix[i][j - 1] + \
                              matrix[i - 2][j - 1] + matrix[i - 2][j]

    # Return the nth Delannoy number
    return matrix[n][0]
```

