import math

def count_Fac(num):
    distinct_factors = set()
    # Divide num by 2 to remove all even factors
    while num % 2 == 0:
        distinct_factors.add(2)
        num //= 2
    # Now num must be odd, start checking from 3
    for i in range(3, int(math.sqrt(num)) + 1, 2):
        # While i divides num, add i and divide num it num
        while num % i == 0:
            distinct_factors.add(i)
            num //= i
    # This condition is to check if num is a prime number greater than 2
    if num > 2:
        distinct_factors.add(num)
    return len(distinct_factors)
