    if nums[-1] >= nums[high]:
        return nums[-1]
    # If the list is not rotated, the maximum is the last element
    if low >= high:
        return nums[low]
    # Find the middle of the array
    mid = low + (high - low) // 2
    # Check if the middle element is greater than both the left and right
    if mid > 0 and nums[mid] > nums[mid - 1]:
        return nums[mid]
    # If the middle element is greater than the last element, the maximum is in the left part
    elif nums[mid] > nums[high]:
        return find_Max(nums, low, mid - 1)
    # If the middle element is smaller than or equal to the last element, the maximum is in the right part
    else:
        return find_Max(nums, mid + 1, high)
