def max_product(numbers):
    if not numbers:
        return None

    # Initialize the maximum and second maximum numbers
    max1, max2 = float('-inf'), float('-inf')
    min1, min2 = float('inf'), float('inf')

    for number in numbers:
        # Update the max elements
        if number > max1:
            max2, max1 = max1, number
        elif number > max2:
            max2 = number

        # Update the min elements
        if number < min1:
            min2, min1 = min1, number
        elif number < min2:
            min2 = number

    # Calculate the maximum product of the largest and second largest, and the largest and smallest
    product1 = max1 * max2
    product2 = max1 * min2

    # Return the maximum of the two products
    return (max(product1, product2), max1, max2)
