```python
def max_product(nums):
    # Initialize the smallest and largest values
    min1, min2 = float('inf'), float('inf')
    max1, max2 = float('-inf'), float('-inf')

    # Iterate through the array to find the maximum and minimum values
    for num in nums:
        # Update the highest and lowest values
        if num <= min1:
            min2 = min1
            min1 = num
        elif num <= min2:
            min2 = num

        if num >= max1:
            max2 = max1
            max1 = num
        elif num >= max2:
            max2 = num

    # Calculate the product of the two largest and the two smallest numbers
    return max(max1 * max2, min1 * min2)
```

