```python
def nCr_mod_p(n, r, p):
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1
    if r == 1:
        return n
    # Create Pascal's triangle up to nCr
    Pascal = [[0 for _ in range(r+1)] for _ in range(n+1)]
    for i in range(n+1):
        Pascal[i][0] = 1
        if i == 1:
            continue
        for j in range(1, i):
            Pascal[i][j] = (Pascal[i-1][j-1] + Pascal[i-1][j]) % p
        Pascal[i][i] = 1
    return Pascal[n][r]
```

```python
def nCr_mod_p(n, r, p):
    # Helper function to factorial modulo p
    def factorial_mod(a, mod):
        if a == 0 or a == 1:
            return 1
        result = 1
        for i in range(2, a + 1):
            result = (result * i) % mod
        return result

    # Calculate nCr mod p
    return (factorial_mod(n, p) * factorial_mod(1, p)) // (factorial_mod(r, p) * factorial_mod(n - r, p)) % p
```

