def remove_nested(record):
    # Initializing an empty list to store the result
    result = []
    for item in record:
        # Check if the item is a tuple. If yes, recursively remove the nested tuple
        if isinstance(item, tuple): 
            result.extend(remove_nested(item))
        else:
            # If not a tuple, append the item to the result list
            result.append(item)
    return tuple(result)
