def find_kth(arr1, arr2, k, ind1, ind2):
    while ind1 < len(arr1) and ind2 < len(arr2):
        if arr1[ind1] < arr2[ind2]:
            arr1[ind1], arr2[k-ind1-ind2] = arr2[k-ind1-ind2], arr1[ind1]
            ind1 += 1
        else:
            arr2[ind2], arr2[k-ind1-ind2] = arr2[k-ind1-ind2], arr2[ind2]
            ind2 += 1
    if ind1 < len(arr1):
        for i in range(ind1, k):
            arr1[i], arr2[k-ind1-i-1] = arr2[k-ind1-i-1], arr1[i]
    return arr1[k-1]
```

