def find_kth(arr1, arr2, n, m, k):
    # If first array is empty, return the kth element from second array
    if n == 0:
        return arr2[k - 1]

    # If second array is empty, return the kth element from first array
    if m == 0:
        return arr1[k - 1]

    # If k is 1, return the smaller of the first elements or the kth smallest element from both arrays
    if k == 1:
        return min(arr1[0], arr2[0])

    # Divide k into two halves, one for the first array and one for the second array
    i = n // 2
    j = m // 2

    # If first element of first array is smaller, move the pointer of first array to the right
    if arr1[i] <= arr2[j]:
        return find_kth(arr1[i + 1:], arr2, n - i - 1, m, k - i - 1)

    # Else, move the pointer of second array to the right
    else:
        return find_kth(arr1, arr2[j + 1:], n, m - j - 1, k - j - 1)
```

