def find_kth(arr1, arr2, n1, n2, k):
    if n1 > n2:
        return find_kth(arr2, arr1, n2, n1, k)
    if n1 == 0:
        return arr2[k-1]
    if k == 1:
        return min(arr1[0], arr2[0])
    mid1 = n1 // 2
    mid2 = n2 // 2
    if arr1[mid1] == arr2[mid2]:
        return arr1[mid1]
    if mid1 + 1 >= k:
        return find_kth(arr1[:mid1], arr2, mid1, n2, k)
    elif mid2 + 1 >= k:
        return find_kth(arr1, arr2[:mid2], n1, mid2, k)
    if mid1 + mid2 + 1 >= k:
        return min(arr1[mid1], arr2[mid2])
    else:
        return find_kth(arr1[mid1+1:], arr2[mid2+1:], n1 - mid1 - 1, n2 - mid2 - 1, k - (mid1 + mid2 + 1))

# Test case
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5, 4, 5) == 6
