    # Base case: There is one way to tile a 1x1 square
    if n == 1:
        return 1
    # Recursive case: We can tile a 2x_n square in two ways: either tile a 1x1 square alone, or tile a 2x1 square followed by n-1 ways to tile a 1x_n-1 square
    else:
        return get_noOfways(n-1) + get_noOfways(n-2)
