def get_noOfways(n):
    def dp(k):
        table = [0] * (k + 1)
        table[0], table[1] = 1, 1

        for i in range(2, k + 1):
            table[i] = table[i - 1] + table[i - 2]

        return table[n]

    total_ways = 0
    for i in range(0, n + 1, 2):
        total_ways += dp(i)

    return total_ways
