    if n % 2 == 0:
        # Check if every even-indexed character is different from every odd-indexed character
        for i in range(0, n, 2):
            if s[i] == s[i+1]:
                return False
    # If the length of the string is odd
    # The string must be made up of two alternating characters
    else:
