def maxAverageOfPath(matrix, n):
    def calculatePathSum(board, path, i, j):
        if i < 0 or j < 0 or i >= n or j >= n or board[i][j] == None:
            return 0
        path.append(board[i][j])
        if len(path) == n:
            return sum(path)
        pathSums = [calculatePathSum(board, path, i + 1, j), calculatePathSum(board, path, i - 1, j), calculatePathSum(board, path, i, j + 1), calculatePathSum(board, path, i, j - 1)]
        path.pop()
        return max(pathSums) if pathSums else 0

    maxSum = float('-inf')
    for i in range(n):
        for j in range(n):
            currentSum = calculatePathSum(matrix, [], i, j)
            if currentSum > maxSum:
                maxSum = currentSum
    return maxSum/n
```

The function `maxAverageOfPath` calculates the maximum average over all existing paths for the given square matrix. It uses a recursive helper function `calculatePathSum` to explore all possible paths from the current cell `(i, j)` to the last cell `(n-1, n-1)`. It keeps track of the sum of each path and updates the maximum sum encountered. Finally, it returns the average of the maximum sum, normalizing it by the size of the matrix.

```python
from typing import List

def maxAverageOfPath(matrix: List[List[int]], n: int) -> float:
    def dfs(i, j, path_sum, path_count):
        nonlocal max_path_sum, max_path_count
        if path_count == n:
            max_path_sum = max(max_path_sum, path_sum / path_count)
            return
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = i + dx, j + dy
            if 0 <= nx < n and 0 <= ny < n:
                dfs(nx, ny, path_sum + matrix[nx][ny], path_count + 1)

    max_path_sum = -float('inf')
    max_path_count = 0
    for i in range(n):
        for j in range(n):
            dfs(i, j, matrix[i][j], 1)
    return max_path_sum
```

