def lcm(x, y):
    # Calculate the prime factors of x and y
    prime_factors_x = {}
    prime_factors_y = {}
    for i in range(2, x + 1):
        while x % i == 0:
            prime_factors_x[i] = prime_factors_x.get(i, 0) + 1
            x //= i
    for i in range(2, y + 1):
        while y % i == 0:
            prime_factors_y[i] = prime_factors_y.get(i, 0) + 1
            y //= i

    # Find the intersection of the prime factors of x and y
    common_factors = set(prime_factors_x.keys()).intersection(set(prime_factors_y.keys()))

    # Calculate the lcm
    lcm = 1
    for factor in common_factors:
        lcm *= factor ** max(prime_factors_x[factor], prime_factors_y[factor])
    for factor in set(prime_factors_x.keys()).symmetric_difference(set(prime_factors_y.keys())):
        lcm *= factor

    return lcm
