import numpy as np

def generate_matrix(n):
    matrix = np.zeros((n, n), dtype=int)
    i = k = t = l = 100

    while i * i <= n:
        for j in range(k, t):
            matrix[i][j] = l
            l += 1
        k += 1

        for j in range(k, t):
            matrix[j][i] = l
            l += 1
        i += 1

        for j in range(t - 1, i - 1, -1):
            matrix[t - 1][j] = l
            l += 1
        t -= 1

        for j in range(t - 1, i - 1, -1):
            matrix[j][i - 1] = l
            l += 1
        i -= 1

        if k > i:
            break

    return matrix.tolist()
```

```python
def generate_matrix(n):
    matrix = [[0]*n for _ in range(n)]
    num = 1
    top, bottom, left, right = 0, n-1, 0, n-1

    while top <= bottom and left <= right:
        for i in range(left, right+1):
            matrix[top][i] = num
            num += 1
        top += 1

        for i in range(top, bottom+1):
            matrix[i][right] = num
            num += 1
        right -= 1

        if top <= bottom:
            for i in range(right, left-1, -1):
                matrix[bottom][i] = num
                num += 1
            bottom -= 1

        if left <= right:
            for i in range(bottom, top-1, -1):
                matrix[i][left] = num
                num += 1
            left += 1

    return matrix
```

