def remove_duplicate(lst):
    # Initialize an empty dictionary to keep track of duplicates
    duplicates = {}
    result = []

    # Iterate over each sublist in the input list
    for sublist in lst:
        # Check if the sublist is already in the duplicates dictionary
        if '/'.join(map(str, sublist)) in duplicates:
