    if x-1 >= 0 and y-1 >= 0:
        adjacent_coords.append((x-1, y-1))
    # Check upper center coordinate
    if x-1 >= 0 and y >= 0:
        adjacent_coords.append((x-1, y))
    # Check upper right coordinate
    if x-1 >= 0 and y+1 <= 4:
        adjacent_coords.append((x-1, y+1))
    # Check left coordinate
    if x >= 0 and y-1 >= 0:
        adjacent_coords.append((x, y-1))
    # Check right coordinate
    if x >= 0 and y+1 <= 4:
        adjacent_coords.append((x, y+1))
    # Check lower left coordinate
    if x+1 <= 4 and y-1 >= 0:
        adjacent_coords.append((x+1, y-1))
    # Check lower center coordinate
    if x+1 <= 4 and y >= 0:
        adjacent_coords.append((x+1, y))
    # Check lower right coordinate
    if x+1 <= 4 and y+1 <= 4:
        adjacent_coords.append((x+1, y+1))
    return adjacent_coords
