import heapq

def expensive_items(data, n):
    # Using a min-heap to track the n most expensive items
    min_heap = []
    for item in data:
        if len(min_heap) < n:
            heapq.heappush(min_heap, (item['price'], item['name']))
        elif item['price'] > min_heap[0][0]:
            heapq.heappushpop(min_heap, (item['price'], item['name']))
    # Return the list of items from the heap
    return [item[1] for item in min_heap]
