def max_sum_of_three_consecutive(nums, n):
    if n < 3:
        return sum(nums)
    max_sum = max(nums[:3])
    current_sum = nums[0] + nums[1] + nums[2]
    for i in range(3, n):
        current_sum = max(current_sum - nums[i-3] + nums[i], max_sum)
        max_sum = max(max_sum, current_sum)
    return max_sum
