def max_sum_of_three_consecutive(arr, n):
    if n < 3:
        return "Array too short"
    # Initialize the dp array
    dp = [0] * n
    dp[0], dp[1], dp[2] = arr[0], arr[0] + arr[1], arr[0] + arr[1] + arr[2]
    # Fill the dp array
    for i in range(3, n):
        dp[i] = max(dp[i-1], dp[i-2], dp[i-3]) + arr[i]
    # Return the maximum value
    return max(dp)
