def min_sum_path(triangle):
    # Update each element with the minimum path sum from the top
    for i in range(1, len(triangle)):
        for j in range(len(triangle[i])):
            # For the first element in the triangle, the path sum is the value itself
            if j == 0:
                triangle[i][j] += triangle[i-1][j]
            # For the last element in the triangle, the path sum is the value itself
            elif j == len(triangle[i]) - 1:
                triangle[i][j] += triangle[i-1][j-1]
            else:
                # For other elements, the path sum is the minimum of the path sums from the top two positions
                triangle[i][j] += min(triangle[i-1][j], triangle[i-1][j-1])
    # Return the minimum path sum of the last row
    return min(triangle[-1])
