def lcs_of_three(string1, string2, string3:
    m = len(string1)
    n = len(string2)
    o = len(string3)

    # Create a 3D table to store lengths of longest common subsequence end of sub-strings
    L = [[[0 for _ in range(o + 1)] for _ in range(n + 1)] for _ in range(m + 1)]

    # Build the L[m+1][n+1][o+1] table 
    for i in range(m + 1):
        for j in range(n + 1):
            for k in range(o + 1):
                if i == 0 or j == 0 or k == 0:
                    L[i][j][k] = 0
                elif string1[i - 1] == string2[j - 1] == string3[k - 1]:
                    L[i][j][k] = L[i - 1][j - 1][k - 1] + 1
                else:
                    L[i][j][k] = max(L[i][j - 1][k], L[i - 1][j][k - 1], L[i - 1][j - 1][k - 1])

    # The value at L[m][n][o] will be the length of the longest common subsequence
    return L[m][n][o]
