def find_Min_Swaps(arr, n):
    swaps = 0
    for i in range(n):
        while arr[i] == 1:
            index_max = i
            for j in range(i + 1, n):
                if arr[j] == 0:
                    index_max = j
                    break
            if index_max != i:
                arr[i], arr[index_max] = arr[index_max], arr[i]
                swaps += 1
    return swaps
```

```python
def find_Min_Swaps(arr, n):
    min_swaps = 0
    for i in range(n):
        if arr[i] == 1:
            left = i
            while left < n-1 and arr[left] == 0:
                left += 1
            right = left + 1
            while right < n and arr[right] == 1:
                right += 1
            min_swaps += abs(left - right)
            arr[:left] = arr[:left][::-1]
            for j in range(left, right):
                arr[j] = 1
    return min_swaps
```

