class Solution:
    def minSwaps(self, a: str, b: str) -> int:
        if a == b:
            return 0
        c = 0
        i = 0
        j = 0
        while i < len(a) and j < len(b):
            if a[i] != b[j]:
                c += 1
                i += 1
            else:
                i += 1
                j += 1
        return c
```

