def rgb_to_hsv(r, g, b):
    r /= 255
    g /= 255
    b /= 255

    mx = max(r, g, b)
    mn = min(r, g, b)

    if mx == mn:
        h = 0
    elif mx == r:
        h = (60 * ((g - b) / (mx - mn)) + 360) % 360
    elif mx == g:
        h = (60 * ((b - r) / (mx - mn)) + 120) % 360
    elif mx == b:
        h = (60 * ((r - g) / (mx - mn)) + 240) % 360

    if mx == 0:
        s = 0
    else:
        s = ((mx - mn) / mx) * 100

    v = mx * 100

    return h, s, v
```

