    diff = max_color - min_color
    if max_color == 0:
        h = 0
    elif max_color == r:
        h = (60 * ((g - b) / diff)) % 360
    elif max_color == g:
        h = (60 * ((b - r) / diff)) + 120
    else:
        h = (60 * ((r - g) / diff)) + 240
    if max_color == 0:
