def rgb_to_hsv(r, g, b):
    max_val = max(r, g, b)
    min_val = min(r, g, b)
    diff = max_val - min_val
    hue = 0
    if diff == 0:
        saturation = 0
    else:
        saturation = diff / max_val
        if r == max_val:
            hue = (g - b) / diff % 6
        elif g == max_val:
            hue = (b - r) / diff + 2
        else:
            hue = (r - g) / diff + 4
        hue = hue * 60
    if hue < 0:
        hue += 360
    return (hue, saturation, max_val)
