    result = []
    for i in range(k):
        closest = -1
        for j in range(m):
            for l in range(n):
                potential = abs(arr1[i] - arr2[j - 1]) + abs(arr2[j] - arr3[l - 1]) + \
                           abs(arr3[l] - arr1[i - 1])
                if closest == -1 or potential < closest:
