def modular_sum(arr, n, m):
    # Check if the total sum is divisible by m
    if sum(arr) % m:
        return False

    # Initialize a DP table
    dp = [[False for _ in range(n + 1)] for _ in range(m + 1)]

    # If the sum is divisible by m, a subset sum of 0 is possible
    dp[0][0] = True

    # Fill the DP table
    for i in range(m + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i][j - 1]  # Exclude the current element
            if arr[j - 1] <= i:
                dp[i][j] |= dp[i - arr[j - 1]][j - 1]  # Include the current element

    # Check if there exists a subset sum divisible by m
    for i in range(m + 1):
        if dp[i][n]:
            return True
    return False
```

