def subset(arr, k):
    # Edge case: If k is greater than the size of the array, return 0
    if k > len(arr):
        return 0

    # Initialize a boolean array to mark elements as seen
    seen = [False] * len(arr)

    # Function to count subsets with distinct elements
    def count_subsets(is_subset):
        # Base case: If the current subset has k elements, return 1
        if is_subset == k:
            return 1
        c1 = 0  # Subsets count with the current element
        for i in range(len(arr)):
            if seen[i] == False:
                seen[i] = True
                c1 += count_subsets(is_subset + 1)
                seen[i] = False
        return c1

    return count_subsets(0)
```

