def count_Rotation(arr, n):
    if n <= 1:
        return n
    start, end = 0, n - 1
    while start < end:
        if arr[start] <= arr[end]:
            return 0
        mid = start + (end - start) // 2
        if arr[mid] > arr[end]:
            start = mid + 1
        else:
            end = mid
    return start
