def find_kth_element(arr1, arr2, k):
    if not arr1:
        return arr2[k - 1]
    if not arr2:
        return arr1[k - 1]
    if k == 1:
        return min(arr1[0], arr2[0])

    mid1 = len(arr1) // 2
    mid2 = len(arr2) // 2

    if arr1[mid1] > arr2[mid2]:
        return find_kth_element(arr1[:mid1], arr2[mid2:], k - mid2)
    else:
        return find_kth_element(arr1[mid1:], arr2[:mid2], k - mid1)
