    # Ensure nums1 is the smaller array
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    low, high = 0, n
    while low <= high:
        i = (low + high) // 2
        j = n - i

        # Check if partition is correct
        if (i == 0 or nums1[i - 1] <= nums2[j]) and (i == n or nums1[i] >= nums2[j - 1]):
            if n % 2 == 1:
                return float(nums1[i] if i < n else nums2[j])
            else:
                return (nums1[i] + nums2[j]) / 2.0
        elif nums1[i] > nums2[j]:
            high = i - 1
        else:
            low = i + 1

