def super_seq(str1, str2, m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to find the shortest common supersequence
    i, j = m, n
    superseq = []
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            superseq.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            superseq.append(str1[i - 1])
            i -= 1
        else:
            superseq.append(str2[j - 1])
            j -= 1

    while i > 0:
        superseq.append(str1[i - 1])
        i -= 1

    while j > 0:
        superseq.append(str2[j - 1])
        j -= 1

    # Reverse the seq to get the correct order
    superseq.reverse()
    return len(superseq) + m - dp[m][n]
