def min_coins(coins, m, V):
    dp = [0 for i in range(V + 1)]
    for i in range(1, V + 1):
        dp[i] = float('inf')
        for j in range(m):
            if coins[j] <= i:
                dp[i] = min(dp[i], dp[i - coins[j]] + 1)
    return dp[V]
```

```python
def min_coins(coins, n, value):
    # Create a 2D list where dp[i][j] stores minimum number of coins to make value i
    dp = [[float('inf')] * (value + 1) for _ in range(n + 1)]

    dp[0][0] = 0  # Base case: to make 0 value using 0 coins

    # Fill the dp table
    for coin in range(n):
        for i in range(value + 1):
            if coins[coin] <= i:
                dp[coin + 1][i] = min(dp[coin +1][i], dp[coin][i - coins[coin]] + 1)
            else:
                dp[coin + 1][i] = dp[coin][i]

    # The result is in dp[n][value]
    return dp[n][value] if dp[n][value] != float('inf') else -1
```

