    for sublist in list_of_lists:
        # Convert tuple of sublist to a sorted tuple for hashing
        sorted_sublist = tuple(sorted(sublist))
        # If the sorted sublist is already in the dictionary, increment its count
        if sorted_sublist in unique_count:
            unique_count[sorted_sublist] += 1
        # Otherwise, add the sorted sublist with a count of 1
        else:
            unique_count[sorted_sublist] = 1
    return unique_count
