def count_Fac(num):
    from math import sqrt
    unique_factors = set()  # Use a set to store unique factors
    for i in range(2, int(sqrt(num)) + 1):
        while num % i == 0:
            unique_factors.add(i)
            num //= i  # Remove all factors of i
    # Add the remaining prime number if not handled
    if num > 1:
        unique_factors.add(num)
    return len(unique_factors)

