def check(arr, n):
    # Check if the array length is less than 2, then it's always sorted
    if n < 2:
        return True
    # Initialize the minimum and maximum values with the first two elements
    min_val = min(arr[0], arr[1])
    max_val = max(arr[0], arr[1])
    # Iterate through the array to find out if sorting is possible
    for i in range(2, n):
        if arr[i] < min_val or arr[i] > max_val:
            return False
        # Update the minimum and maximum values
        if arr[i] <= min_val:
            min_val = arr[i]
        elif arr[i] >= max_val:
            max_val = arr[i]
    return True
