def find_longest_conseq_subseq(nums, n):
    # Create a boolean array to keep track of numbers that are part of a sequence
    seq_status = [False] * n
    for i in range(n):
        seq_status[i] = True

    # Update the sequence status for consecutive numbers
    for i in range(n):
        if seq_status[i]:
            current_num = nums[i]
            while current_num <= n - 1 and seq_status[current_num]:
                seq_status[current_num] = False
                current_num += 1

    # Count the number of sequences
    max_length = 0
    current_length = 0
    for status in seq_status:
        if status:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 0

    return max_length
