    if n <= 1:
        return n

    hash_map = {}
    for i in range(n):
        if arr[i] not in hash_map:
            hash_map[arr[i]] = 1

    max_len = 0

    for i in range(n):
        current_num = arr[i]
        length = 1

        while current_num + 1 in hash_map:
            current_num += 1
            length += 1

        max_len = max(max_len, length)

    return max_len
