def lcs_of_three(s1, s2, s3, m, n, o):
    # Initialize a 3D array for memoization
    dp = [[[0 for _ in range(o+1)] for _ in range(n+1)] for _ in range(m+1)]

    # Build the DP table from bottom up
    for i in range(1, m+1):
        for j in range(1, n+1):
            for k in range(1, o+1):
                if s1[i-1] == s2[j-1] == s3[k-1]:
                    dp[i][j][k] = 1 + dp[i-1][j-1][k-1]
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    # The bottom-right cell will contain the length of the longest common subsequence
    return dp[m][n][o]
```

