def lcs_of_three(s1, s2, s3, m, n, o): 
    # Create a table to store lengths of longest common subsequence 
    # of substrings. dp[i][j][k] stores longest common subsequence 
    # length of s1[0..i-1], s2[0..j-1], s3[0..k-1] 
    dp = [[[0 for i in range(o+1)] for j in range(n+1)] for k in range(m+1)] 

    # Build the table in bottom-up manner 
    for i in range(1, m+1): 
        for j in range(1, n+1): 
            for k in range(1, o+1): 
                if s1[i-1] == s2[j-1] == s3[k-1]: 
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else: 
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1]) 

    # The length of longest common subsequence of first three strings will be in 
    # dp[m][n][o] 
    return dp[m][n][o] 
