def max_sum_increasing_subsequence(arr, n):
    # Initialize dp array
    dp = [0] * n

    # Base case: The maximum sum of increasing subsequence of a single element is the element itself
    for i in range(n):
        dp[i] = arr[i]

    # Compute the maximum sum of increasing subsequences
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]

    # The maximum value in dp array is the maximum sum of increasing subsequence
    return max(dp)
```

