def max_sum_of_three_consecutive(nums, n):
    if n < 3:
        return 0
    dp = [0] * (n + 1)
    dp[1], dp[2] = nums[0], nums[0] + nums[1]
    for i in range(3, n + 1):
        dp[i] = max(dp[i - 1], dp[i - 2], dp[i - 3] + nums[i - 1])
    return dp[n]
```

```python
def max_sum_of_three_consecutive(nums, n):
    if n < 3:
        return sum(nums)
    dp = [0] * n
    dp[0], dp[1] = nums[0], nums[0] + nums[1]
    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + nums[i], dp[i-3] + nums[i] + nums[i-1])
    return dp[n-1]

