def count_Rotation(arr, n): 
    low = 0
    high = n - 1

    while low < high: 
        mid = low + (high - low) // 2
        if arr[mid] > arr[high]: 
            low = mid + 1
        elif arr[mid] < arr[high]: 
            high = mid 
        else: 
            high -= 1

    return low 
