    while high >= low:
        mid = (low + high) // 2
        if (mid == 0 or arr[mid] < arr[mid - 1]) and (mid == n - 1 or arr[mid] < arr[mid + 1]):
            return mid + 1
        if arr[low] > arr[mid]:
            high = mid - 1
        else:
            low = mid + 1
    return 0

