class Pair:
    def __init__(self, first, second):
        self.first = first
        self.second = second

def max_chain_length(pairs, n):
    # Initialize a list to keep track of the maximum chain length
    chain = [1] * n

    # Sort the pairs by the second element
    pairs.sort(key=lambda x: x.second)

    # Iterate through each pair
    for i in range(1, n):
        for j in range(i):
            # If pair A can be chained with pair B, update the chain length
            if pairs[i].first >= pairs[j].second and chain[i] < chain[j] + 1:
                chain[i] = chain[j] + 1

    # The maximum value in the chain array gives the max length chain
    return max(chain)

