def dealnnoy_num(n, k):
    if n < 1 or k < 1:
        return 0
    if n == 1 or k == 1:
        return 1
    if k == 2:
        return n

    dp = [0] * (k + 1)
    dp[1] = 1
    dp[2] = 2

    for i in range(3, n + 1):
        dp[i] = dp[i - 1] * (k + i - 1) // i

    return dp[k]
```

