def dealnnoy_num(n, m):
    def_cache = {}
    def find(n, m):
        if (n, m) in def_cache:
            return def_cache[(n, m)]
        if n == m == 0:
            return 1
        elif n < m:
            return 0
        else:
            def_cache[(n, m)] = find(n-1, m) + find(n, m-1) + find(n-1, m-1)
            return def_cache[(n, m)]
    return find(n, m)
