import math

def dealnnoy_num(n, k):
    # Helper function to calculate the binomial coefficient
    def binomial_coefficient(n, k):
        return math.factorial(n) // (math.factorial(k) * math.factorial(n - k))

    # Calculate the nth delannoy number
    delnoy_num = 0
    for i in range(k + 1):
        delnoy_num += binomial_coefficient(n + 1, i) * binomial_coefficient(k + 1, k - i)
    return delnoy_num
```

