import heapq
def nth_super_ugly_number(n, primes):
    if n <= 0 or len(primes) == 0:
        return -1

    heap = [1]
    ugly_numbers = set()

    for _ in range(n):
        current_ugly = heapq.heappop(heap)
        ugly_numbers.add(current_ugly)
        for prime in primes:
            next_ugly = current_ugly * prime
            if next_ugly not in ugly_numbers:
                heapq.heappush(heap, next_ugly)

    return sorted(ugly_numbers)[n-1]
