        return 0

    # Initialize the dp array with 1s, as each number is its own base case
    dp = [1] * len(nums)

    # Iterate through the array to compute the dp array
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in dp array represents the length of the longest increasing subsequence
    return max(dp)
